const fs = require("fs"), path = require("path");
const dir = ".verify-neg";
function readNum(name) {
  const p = path.join(dir, name);
  if (!fs.existsSync(p)) { console.error(`FAIL: required file ${name} is missing`); process.exit(1); }
  const n = Number(fs.readFileSync(p, "utf8").trim());
  if (!Number.isFinite(n)) { console.error(`FAIL: ${name} is not numeric`); process.exit(1); }
  return n;
}
const seed = readNum("seed.txt"), s1 = readNum("stage1.txt"), s2 = readNum("stage2.txt"), s3 = readNum("stage3.txt");
const checks = [["stage1 = seed + 2", s1, seed + 2], ["stage2 = stage1^2", s2, s1 * s1], ["stage3 = stage2 - 4", s3, s2 - 4]];
let ok = true;
for (const [label, got, want] of checks) { const pass = got === want; if (!pass) ok = false; console.log(`${pass ? "PASS" : "FAIL"}: ${label} -> expected ${want}, found ${got}`); }
process.exit(ok ? 0 : 1);
'
echo "negative-case exit code: $?"
rm -rf .verify-neg && echo "cleaned up .verify-neg" && ls

